from typing import List

class Solution:
    def numberOfSequence(self, n: int, sick: List[int]) -> int:
        MOD = 10**9 + 7
        sick = [-1] + sick + [n]
        ans = 1
        for i in range(1, len(sick)):
            left = sick[i - 1] + 1
            right = sick[i] - 1
            length = right - left + 1
            if length == 0:
                continue
            
            ways = 1
            if length > 2:
                ways = self.combinations(length - 1, (length // 2) - 1 if length % 2 == 0 else length // 2) * 2 % MOD

            ans = (ans * ways) % MOD

        return ans

    def factorial(self, n: int) -> int:
        res = 1
        for i in range(1, n + 1):
            res = res * i
        return res

    def combinations(self, n: int, r: int) -> int:
        if r < 0 or r > n:
            return 0
        if r == 0 or r == n:
            return 1
        if r > n // 2:
            r = n - r

        res = 1
        for i in range(r):
            res = res * (n - i) // (i + 1)
        return res
